	"gift_premium_subtitle": "Schenke %2$s ein Jahr %1$s für %3$s. Wenn du die Zahlung abgeschlossen hast, erhält die Person eine Mitteilung, dass du ihr das Geschenk gesendet hast.",
	"gift_premium_terms_footer": "Der Preis des Geschenkabonnements wird beim Kauf in Rechnung gestellt und nicht zurückerstattet. Das Geschenk kann nur einmal genutzt werden, wird nicht ersetzt, kann nicht kombiniert werden und hat keinen Barwert. Das Abonnement beginnt, nachdem X es geprüft und dem Empfänger zugewiesen hat, der unsere %1$s und unsere Richtlinien annehmen muss. Wenn der Empfänger nicht alle Voraussetzungen für die Teilnahmeberechtigung erfüllt, das Abonnement storniert oder unsere Bedingungen und Richtlinien ablehnt, kann das Geschenk nicht eingelöst werden und wird auch nicht zurückerstattet. Steuern können anfallen. Bedingungen können sich ändern. %2$s.",
