	"go_to_twitter": "Gehe zu x.com",
	"golive__tip_broadcaster_1": "<b>TIPP:</b> Vielen Dank, dass du live gegangen bist! Begrüße die Zuschauer, indem du „Hallo“ sagst, wenn sie dein Video einschalten.",
	"golive__tip_broadcaster_10": "<b>TIPP:</b> Vielen Dank, dass du auf X live gehst! ≺3",
	"golive__tip_broadcaster_2": "<b>TIPP:</b> Erwähne Personen mit Namen, wenn sie dein Live-Video einschalten – sie werden sich freuen!",
	"golive__tip_broadcaster_3": "<b>TIPP:</b> Sende mindestens ein paar Minuten lang live, damit man dich leichter finden kann.",
	"golive__tip_broadcaster_4": "<b>TIPP:</b> Frage deine Zuschauer, woher sie kommen – so kannst du schnell das Eis brechen.",
	"golive__tip_broadcaster_5": "<b>TIPP:</b> Bedanke dich, dass die Zuschauer eingeschaltet haben, und reagiere auf ihre Kommentare, damit sie weiterhin zusehen.",
	"golive__tip_broadcaster_6": "<b>TIPP:</b> Wenn du während der Sendung keinen Empfang hast, gehe an einen Ort, wo der Empfang besser ist.",
	"golive__tip_broadcaster_7": "<b>TIPP:</b> Bitte die Zuschauer, dir zu folgen, damit sie beim nächsten Mal, wenn du live gehst, eine Mitteilung erhalten.",
	"golive__tip_broadcaster_8": "<b>TIPP:</b> Beginne dein Video, indem du als Erstes „Hallo“ sagst. Zuschauern, die es sich später ansehen, wird das gefallen.",
	"golive__tip_broadcaster_9": "<b>TIPP:</b> Bedanke dich, dass die Zuschauer eingeschaltet haben, bevor du das Live-Video endest.",
	"golive__tip_pre_broadcast_1": "<b>TIPP:</b> Schreibe einen Titel, bevor du live gehst, damit dein Video einfacher zu entdecken ist.",
	"golive__tip_pre_broadcast_2": "<b>TIPP:</b> Ein beschreibender Titel hilft Personen, leichter zu verstehen, worum es in deinem Live-Video geht.",
	"golive__tip_pre_broadcast_3": "<b>TIPP:</b> Du brauchst Ideen? Mach eine Tour, teile ein Talent oder rede über etwas, was dich interessiert.",
	"golive__tip_pre_broadcast_4": "<b>TIPP:</b> Achte vor dem Start der Sendung darauf, dass dein Empfang gut ist.",
	"golive__tip_pre_broadcast_5": "<b>TIPP:</b> Füge ein Hashtag zu deinem Titel hinzu, damit dein Live-Video leichter zu entdecken ist.",
	"golive__tip_pre_broadcast_6": "<b>TIPP:</b> Das sind alle Tipps für den Moment – vielen Dank, dass du auf X live gehst!",
