	"identity_education_cancel": "Nicht jetzt",
	"identity_education_conditions": "Ich erkläre mich damit einverstanden, dass X und Au10tix Bilder meines Ausweises und mein Selfie, einschließlich extrahierter biometrischer Daten, zur Bestätigung meiner Identität und für die damit verbundenen Sicherheitszwecke von X nutzen, u. a. zur Verhinderung von Identitätsbetrug. Au10tix darf solche Daten bis zu 30 Tage lang speichern. {{}}Mehr erfahren{{}}",
	"identity_education_conditions_age_verification": "Ich erkläre mich damit einverstanden, dass X und Persona anhand von Bildern meines Ausweises und meinem Foto mein Alter bestätigen. Dein Foto wird nicht gespeichert. X und xAI speichern möglicherweise Informationen über dein Alter. {{}}Mehr erfahren{{}}",
	"identity_education_conditions_eea": "\"Ich erkläre mich damit einverstanden, dass X Bilder von meinem Ausweis, einschließlich biometrischer Daten, und personenbezogene Daten aus meinem Profil zur Bestätigung meiner Identität an Au10tix weiterleitet.\nIch erkläre mich außerdem damit einverstanden, das X meine Ausweisbilder, einschließlich biometrischer Daten, bis zu 30 Tage lang speichert und sie sowie Daten aus meinem Profil zu Sicherheitszwecken nutzt, u. a. zur Verhinderung von Identitätsbetrug. {{}}Mehr erfahren{{}}\"",
	"identity_education_conditions_persona_vendor": "Ich erkläre mich damit einverstanden, dass X und Persona Bilder meines Ausweises und mein Selfie, einschließlich extrahierter biometrischer Daten, zur Bestätigung meiner Identität und für die damit verbundenen Zwecke bei X im Zusammenhang mit Sicherheit, Betrugsprävention und Zahlung nutzen. Persona darf solche Daten bis zu 30 Tage lang speichern. X darf den vollständigen Namen, die Adresse und Hashes meiner Ausweisdokumentnummer speichern, solange ich den Service X Premium abonniere. {{}}Mehr erfahren{{}}",
