	"payment_funds_insurance_footer_secondary_text": "Weitere Informationen über die FDIC-Versicherung und die Kontobesitzkategorien findest du ﻿hier﻿.",
	"payment_funds_insurance_footer_text": "Deine Einlagen werden von der Cross River Bank, Mitglied der FDIC, verwaltet und sind durch die FDIC bis zu einer Höhe von 250.000 $ pro natürlicher und juristischer Person für alle bei der Bank geführten Konten in jeder Kontoinhaberkategorie (kombiniert) versichert, einschließlich der Konten, die in repräsentativer Funktion geführt werden.",
	"payment_funds_insurance_footer_text_format": "Deine Einlagen werden von der Cross River Bank („der Bank“), Mitglied der FDIC, verwaltet und sind durch die FDIC bis zu einer Höhe von {amount} pro natürlicher und juristischer Person für alle bei der Bank geführten Konten in jeder Kontoinhaberkategorie (kombiniert) versichert, einschließlich der Konten, die in repräsentativer Funktion geführt werden.",
	"payment_funds_insurance_sweep_disclaimer": "Die Einlagen werden bei der Cross River Bank, Mitglied der FDIC, und bei anderen ﻿bei der FDIC versicherten Instituten﻿ gehalten. ﻿Bestimmte Bedingungen﻿ müssen erfüllt sein, damit die Pass-Through-Einlagenversicherungsdeckung gilt. X Payments LLC ist keine von der FDIC versicherte Bank. Die Einlagensicherung deckt nur den Ausfall einer versicherten Bank ab.",
	"payment_funds_insurance_sweep_presentation": "Deine Einlagen werden automatisch in das X Cash-Sweep-Programm aufgenommen, das Zugang zu einer aggregierten FDIC-Versicherungsdeckung von bis zu 10 Mio. USD gewährt (vorbehaltlich bestimmter Einschränkungen). ﻿Mehr erfahren﻿.",
