	"profile_smart_blocked_autoblocked_by_twitter_description": "\"Du bist vorübergehend automatisch von der Anzeige und Interaktion mit Posts von %1$s blockiert worden. Das passiert, wenn der/die Nutzer*in im Sicherheitsmodus war und wir deine Interaktionen als potenziell schädlich oder Spam markiert haben.\n\nWir sind uns bewusst, dass die automatische Blockierung nicht immer richtig entscheidet. Deshalb arbeiten wir an ihrer Verbesserung.\n\n{{}}Was%2$sist%2$sder{{}}Sicherheitsmodus?\n\nHier sind ein paar Tipps, wie du eine sinnvolle Konversation führst und es vermeidest, automatisch blockiert zu werden.\"",
