	"ps__tip_broadcaster_1": "<b>TIPP:</b> Vielen Dank für Dein Live-Video! Begrüße Personen, wenn sie einschalten.",
	"ps__tip_broadcaster_11": "<b>TIPP:</b> Vielen Dank, dass Du auf Periscope sendest! ≺3",
	"ps__tip_broadcaster_2": "<b>TIPP:</b> Nenne Zuschauer, die einschalten, beim Namen. Sie freuen sich bestimmt!",
	"ps__tip_broadcaster_3": "<b>TIPP:</b> Achte darauf, mindestens ein paar Minuten lang zu senden. So können Personen Dich leichter finden.",
	"ps__tip_broadcaster_4": "<b>TIPP:</b> Wenn Du Deine Zuschauer fragst, woher sie kommen, kannst Du damit gut das Eis brechen.",
	"ps__tip_broadcaster_5": "<b>TIPP:</b> Bedanke Dich bei den Zuschauern fürs Einschalten und antworte auf ihre Kommentare, um das Interesse beizubehalten.",
	"ps__tip_broadcaster_6": "<b>TIPP:</b> Wenn während des Sendens die Verbindung abbricht, geh an einen Ort mit besserem Empfang.",
	"ps__tip_broadcaster_7": "<b>TIPP:</b> Bitte Deine Zuschauer, Dir zu folgen, damit sie Mitteilungen erhalten können, wenn Du live gehst.",
	"ps__tip_broadcaster_8": "<b>TIPP:</b> Beginne Dein Live-Video, indem Du Hallo sagst. Die Zuschauer der Aufzeichnung werden das lieben.",
	"ps__tip_broadcaster_9": "<b>TIPP:</b> Bedanke Dich bei den Zuschauern, dass sie eingeschaltet haben, bevor Du das Live-Video endest.",
	"ps__tip_pre_broadcast_1": "<b>TIPP:</b> Schreibe einen Titel, bevor Du das Live-Video startest, und triff Menschen mit ähnlichen Interessen!",
	"ps__tip_pre_broadcast_2": "<b>TIPP:</b> Ein beschreibender Titel hilft Personen, zu verstehen, worum es in Deinem Live-Video geht.",
	"ps__tip_pre_broadcast_3": "<b>TIPP:</b> Du brauchst Ideen? Mach eine Tour, teile ein Talent oder rede über ein Thema, das Dich interessiert.",
	"ps__tip_pre_broadcast_4": "<b>TIPP:</b> Achte vor dem Senden darauf, dass Du guten Handyempfang hast.",
	"ps__tip_pre_broadcast_5": "<b>TIPP:</b> Teile deine Live-Videos auf X und erreiche mehr Zuschauer.",
	"ps__tip_pre_broadcast_6": "<b>TIPP:</b> Wenn Du Personen folgst, die Dir folgen, kannst Du privat an sie senden.",
	"ps__tip_pre_broadcast_8": "<b>TIPP:</b> Füge ein relevantes Hashtag zu Deinem Titel hinzu, damit Personen Dein Live-Video leichter finden können.",
	"ps__tip_pre_broadcast_9": "<b>TIPP:</b> Das sind alle Tipps, die wir im Augenblick haben. Vielen Dank, dass Du Periscope nutzt!",
