	"tipjar_input_rationale": "Zahlungen gehen an den Nutzernamen, den du oben eingegeben hast. Wenn du deinen Nutzernamen hinzufügst und Trinkgelder akzeptierst, legst du damit möglicherweise Informationen über dich offen, die du beim Zahlungsservice angegeben hast, z. B. deinen Namen, deine E-Mail-Adresse und andere Informationen.",
	"tipjar_input_rationale_bitcoin": "Leute senden Zahlungen an die Bitcoin-Adresse, die du oben eingegeben hast.",
	"tipjar_input_rationale_kakao_pay": "\"Spenden gehen an den QR-Link, den du oben eingegeben hast.\nWenn du deinen QR-Link hinzufügst und Spenden akzeptierst, legst du damit möglicherweise Informationen über dich offen, die du beim Zahlungsservice angegeben hast, z. B. deinen Namen, deine E-Mail-Adresse und andere Informationen.\n\nDen QR-Link für Kakao Pay findest du hier: KakaoTalk More > Scanner rechts oben > Money Code > Zwischenablage-Symbol. Wenn du das Symbol antippst, wird der Link in deine Zwischenablage kopiert und du kannst ihn oben einfügen.\"",
	"tipjar_input_rationale_paytm": "Spenden gehen an die mit Paytm verknüpfte Handynummer, die du oben eingegeben hast. Wenn du deine Handynummer hinzufügst und Spenden akzeptierst, legst du damit möglicherweise Informationen über dich offen, die du beim Zahlungsservice angegeben hast, z. B. deinen Namen, deine E-Mail-Adresse, deine Telefonnummer und andere Informationen.",
