	"two_factor_settings_2fa_u2f_security_key_manage_key_description": "Du wirst in deinem Browser bei x.com angemeldet, damit ein Sicherheitsschlüssel umbenannt oder gelöscht werden kann. Wenn du bereits bei einem anderen Account angemeldet bist, melden wir dich dort automatisch ab.",
	"two_factor_settings_2fa_u2f_security_key_manage_key_title": "Deinen Browser öffnen, um Schlüssel zu verwalten?",
	"two_factor_settings_backup_code_summary": "Rufe einen Backup-Code zur einmaligen Nutzung ab, damit du dich bei X anmelden kannst, wenn du keinen Zugriff auf deine Zwei-Faktor-Authentifizierungsoptionen hast. {{}}Mehr erfahren{{}}",
	"two_factor_settings_delete_phone_and_turn_off_2fa": "Damit wird die Telefonnummer aus diesem Account gelöscht und du erhältst in Zukunft keine Benachrichtigungen von X per SMS. Außerdem wird die Zwei-Faktor-Authentifizierung für diesen Account deaktiviert.",
	"two_factor_settings_delete_phone_with_and_disable_sms_2fa": "Damit wird die Telefonnummer aus diesem Account gelöscht und du erhältst in Zukunft keine Benachrichtigungen von X per SMS. Außerdem wird SMS als Methode für die Zwei-Faktor-Authentifizierung für diesen Account deaktiviert.",
	"two_factor_settings_mobile_authenticator_app_title": "Authentifizierungs-App",
	"two_factor_settings_mobile_authenticator_summary": "Hol dir, wenn du dich bei X anmeldest, einen Bestätigungscode über eine Authentifizierungs-App.",
	"two_factor_settings_no_verified_email_dialog_description": "Wenn du die Zwei-Faktor-Authentifizierung einschalten möchtest, musst du eine E-Mail-Adresse mit diesem X Account verknüpfen und sie anschließend bestätigen, damit wir wissen, dass du es wirklich bist.",
	"two_factor_settings_no_verified_email_dialog_title": "E-Mail bestätigen",
	"two_factor_settings_suspended_account_dialog_description": "Dein Account ist derzeit gesperrt. Du kannst daher zurzeit die Zwei-Faktor-Authentifizierung nicht einschalten oder Änderungen an deinen Authentifizierungsmethoden vornehmen.",
	"two_factor_settings_suspended_account_dialog_title": "Etwas ist schiefgelaufen",
	"two_factor_settings_text_message_summary": "Lass dir, wenn du dich bei X anmeldest, eine SMS mit einem Authentifizierungscode an dein Mobiltelefon schicken.",
	"two_factor_settings_u2f_key_management_title": "Deinen Sicherheitsschlüssel verwalten",
	"two_factor_settings_u2f_security_key_summary": "Nutze einen physischen Sicherheitsschlüssel, den du in deinen Computer steckst oder der sich mit deinem Mobilgerät synchronisiert, wenn du dich mit einem unterstützten Webbrowser bei x.com anmeldest. Bei der X App kannst du dich derzeit nicht mit einem Sicherheitsschlüssel anmelden. {{}}Mehr erfahren{{}}",
	"two_factor_settings_u2f_security_key_summary_enabled": "Nutze einen Sicherheitsschlüssel, den du in deinen Computer steckst oder der sich mit deinem Mobilgerät synchronisiert, wenn du dich bei X anmeldest. Du brauchst dazu ein unterstütztes Mobilgerät oder einen unterstützten Webbrowser. {{}}Mehr erfahren{{}}",
	"two_factor_settings_unenroll_description": "Wenn du die Zwei-Faktor-Authentifizierung ausschaltest, ist dein Account anfälliger für Manipulationen. Möchtest du sie wirklich ausschalten?",
